logs=[]
for ep,mp in P.items():
    p=OUT/f'{ep}.md'; t=p.read_text(encoding='utf-8')
    for a,b in sorted(mp.items(),key=lambda x:len(x[0]),reverse=True):
        n=t.count(a)
        if n:
            t=t.replace(a,b); logs.append((ep,a,b,n))
    p.write_text(t,encoding='utf-8')
base=REPORT.read_text(encoding='utf-8') if REPORT.exists() else '# گزارش پاک‌سازی ASR — خانه تو\n'
ls=[base.rstrip(),'','---','','# دور سوم — بازبینی دستی نهایی','']
for ep in range(1,14):
    arr=[x for x in logs if x[0]==ep]; ls.append(f'## قسمت {ep} — {sum(x[3] for x in arr)} اصلاح')
    for _,a,b,n in arr: ls.append(f'- `{a}` → `{b}` × {n}')
    ls.append('')
REPORT.write_text('\n'.join(ls),encoding='utf-8')
print('changes',len(logs),'replacements',sum(x[3] for x in logs))
